.sync-type-container {
  inline-size: 100%;
  position: relative;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--color-surface-border);
  border-radius: 8px;
  block-size: 240px;
  font-size: 1.1rem;
  margin: 0;
  padding: 0;
  background-color: var(--color-surface-base);
  overflow: hidden;
  min-inline-size: 0;

& .sync-input-container {
  display: flex;
  flex-direction: column;
  position: relative;
  overflow-y: auto;
}

& .sync-option {
  padding: var(--hub-sync-list-option-padding);
  gap: var(--hub-sync-list-option-gap);
  line-height: normal;

